// Turn the compact rows into talent objects with ids: t<tree>_<slug>
(function buildTalents() {
  const slug = s => s.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
  for (const cls in TALENT_TREES) {
    TALENT_TREES[cls].forEach((tree, ti) => {
      const rows = tree.talents;
      tree.talents = rows.map(([name, icon, tier, col, max, req, desc, fx]) => ({
        id: `t${ti}_${slug(name)}`, name, icon, tier, col, max, reqName: req || null, desc, fx: fx || {}, tree: ti,
      }));
      for (const t of tree.talents) {
        if (!t.reqName) continue;
        const r = tree.talents.find(x => x.name === t.reqName);
        t.req = r ? r.id : null;
      }
    });
  }
})();

// Fill "{a}" / "{a,b,c}" placeholders for a given rank
function talentText(desc, rank) {
  rank = Math.max(1, rank);
  return desc.replace(/\{([^}]+)\}/g, (m, v) => {
    if (v.includes(',')) { const parts = v.split(','); return parts[Math.min(rank, parts.length) - 1].trim(); }
    const n = parseFloat(v) * rank;
    return String(Math.round(n * 100) / 100);
  });
}
